insert into private.portuguese_bible_story_pool (ordinal, data) values
(1, $story${"id":"biblia-livre-luk-10-25-37","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"O bom samaritano · Lucas 10:25–37"},"summary":{"pt":"25. E eis que um certo estudioso da Lei se levantou, tentando-o, e dizendo: Mestre, o que devo fazer para ter para herdar a vida eterna?\n\n26. E ele lhe disse: O que está escrito na Lei? Como tu a lês?"},"body":{"pt":"25. E eis que um certo estudioso da Lei se levantou, tentando-o, e dizendo: Mestre, o que devo fazer para ter para herdar a vida eterna?\n\n26. E ele lhe disse: O que está escrito na Lei? Como tu a lês?\n\n27. E respondendo ele, disse: Amarás ao Senhor teu Deus de todo teu coração, e de toda tua alma, e de todas tuas forças, e de todo teu entendimento; e amarás a teu próximo como a ti mesmo.\n\n28. E disse-lhe: Respondeste bem; faze isso, e viverás.\n\n29. Mas ele, querendo se justificar, disse a Jesus: E quem é o meu próximo?\n\n30. E respondendo Jesus, disse: Um homem descia de Jerusalém a Jericó, e foi atacado por assaltantes, que também tiraram suas roupas, espancaram-no, e se foram, deixando-o meio morto.\n\n31. E por acaso descia um certo sacerdote pelo mesmo caminho, e vendo-o, passou longe dele .\n\n32. E semelhantemente também um levita, chegando junto a aquele lugar, veio, e vendo-o, passou longe dele\n\n33. Porém um certo samaritano, que ia pelo caminho, veio junto a ele, e vendo-o, teve compaixão dele .\n\n34. E chegando-se, amarrou-lhe um curativo nas feridas, pondo-lhe nelas azeite e vinho; e pondo-o sobre o animal que o transportava, levou-o para uma hospedaria, e cuidou dele.\n\n35. E partindo-se no outro dia, tirou dois dinheiros, e os deu para o hospedeiro; e disse-lhe: Cuide dele; e tudo o que gastares a mais, eu te pagarei quando voltar.\n\n36. Quem, pois, destes três te parece que foi o próximo daquele que foi atacado por assaltantes?\n\n37. Ele disse: Aquele que agiu tendo misericórdia com ele.Então Jesus lhe disse: Vai, e faze da mesma maneira.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK10.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(2, $story${"id":"biblia-livre-luk-15-3-7","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"A ovelha perdida · Lucas 15:3–7"},"summary":{"pt":"3. E ele lhes propôs esta parábola, dizendo:\n\n4. Quem de vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai em busca da perdida, até que a encontre?"},"body":{"pt":"3. E ele lhes propôs esta parábola, dizendo:\n\n4. Quem de vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai em busca da perdida, até que a encontre?\n\n5. E encontrando-a, não a ponha sobre seus ombros, com alegria?\n\n6. E vindo para casa, não convoque aos amigos, e vizinhos, dizendo-lhes: Alegrai-vos comigo, porque já achei minha ovelha perdida?\n\n7. Digo-vos, que assim haverá mais alegria no céu por um pecador que se arrepende, do que por noventa e nove justos que não precisam de arrependimento.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK15.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(3, $story${"id":"biblia-livre-luk-15-11-32","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"O filho que voltou para casa · Lucas 15:11–32"},"summary":{"pt":"11. E disse: Um certo homem tinha dois filhos.\n\n12. E disse o mais jovem deles ao pai: Pai, dá-me a parte dos bens que me pertencem. E ele lhe repartiu os bens."},"body":{"pt":"11. E disse: Um certo homem tinha dois filhos.\n\n12. E disse o mais jovem deles ao pai: Pai, dá-me a parte dos bens que me pertencem. E ele lhe repartiu os bens.\n\n13. E depois de não muitos dias, o filho mais jovem, juntando tudo, partiu-se para uma terra distante, e ali desperdiçou seus bens, vivendo de forma irresponsável.\n\n14. E ele, tendo já gastado tudo, houve uma grande fome naquela terra, e ele começou a sofrer necessidade.\n\n15. E foi, se chegou a um dos cidadãos daquela terra; e este o mandou a seus campos para alimentar porcos.\n\n16. E ele ficava com vontade de encher seu estômago com os grãos que os porcos comiam, mas ninguém as dava para ele.\n\n17. E ele, pensando consigo mesmo, disse: Quantos empregados de meu pai tem pão em abundância, e eu aqui morro de fome!\n\n18. Eu levantarei, e irei a meu pai, e lhe direi: Pai, pequei contra o céu, e diante de ti.\n\n19. E já não sou digno de ser chamado teu filho; faze-me como a um de teus empregados.\n\n20. E levantando-se, foi a seu pai. E quando ainda estava longe, o seu pai o viu, e teve compaixão dele; e correndo, caiu ao seu pescoço, e o beijou.\n\n21. E o filho lhe disse: Pai, pequei contra o céu, e diante de ti; e já não sou digno de ser chamado teu filho.\n\n22. Mas o pai disse a seus servos: Trazei a melhor roupa, e o vesti; e ponde um anel em sua mão, e sandálias nos seus pés.\n\n23. E trazei o bezerro engordado, e o matai; e comamos, e nos alegremos.\n\n24. Porque este meu filho estava morto, e reviveu; tinha se perdido, e foi achado. E começaram a se alegrar.\n\n25. E seu filho mais velho estava no campo; e quando veio, chegou perto da casa, ouviu a música, e as danças.\n\n26. E chamando para si um dos servos, perguntou-lhe: O que era aquilo?\n\n27. E ele lhe disse: Teu irmão chegou; e teu pai matou o bezerro engordado, porque ele voltou são.\n\n28. Porém ele se irritou, e não queria entrar. Então o seu pai, saindo, rogava-lhe que entrasse .\n\n29. Mas o filho respondendo, disse ao pai: Eis que eu te sirvo há tantos anos, e nunca desobedeci tua ordem, e nunca me deste um cabrito, para que eu me alegrasse com meus amigos.\n\n30. Porém, vindo este teu filho, que gastou teus bens com prostitutas, tu lhe mataste o bezerro engordado.\n\n31. E ele lhe disse: Filho, tu sempre estás comigo, e todas as minhas coisas são tuas.\n\n32. Mas era necessário se alegrar e animar; porque este teu irmão estava morto, e reviveu; e tinha se perdido, e foi encontrado.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK15.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(4, $story${"id":"biblia-livre-luk-19-1-10","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus encontra Zaqueu · Lucas 19:1–10"},"summary":{"pt":"1. E Jesus entrou e foi passando por Jericó.\n\n2. E eis que havia ali um homem, chamado pelo nome de Zaqueu, e este era chefe dos publicanos, e era rico."},"body":{"pt":"1. E Jesus entrou e foi passando por Jericó.\n\n2. E eis que havia ali um homem, chamado pelo nome de Zaqueu, e este era chefe dos publicanos, e era rico.\n\n3. E procurava ver quem era Jesus, e não podia, por causa da multidão, pois era pequeno de altura.\n\n4. E correndo com antecedência, subiu em uma árvore de frutos que parecem figos, para o ver; porque ele passaria por ali.\n\n5. E quando Jesus chegou a aquele lugar, olhando para cima, o viu, e disse-lhe: Zaqueu, apressa-te, e desce; porque hoje é necessário que eu fique em tua casa.\n\n6. E apressando-se, desceu, e o recebeu com alegria.\n\n7. E todos, vendo isto , murmuravam, dizendo: Ele entrou para se hospedar com um homem pecador.\n\n8. E Zaqueu, levantando-se, disse ao Senhor: Senhor, eis que dou a metade de meus bens aos pobres; e se eu consegui algo enganando a alguém, eu o devolvo quatro vezes mais.\n\n9. E Jesus lhe disse: Hoje houve salvação nesta casa, porque ele também é filho de Abraão.\n\n10. Porque o Filho do homem veio para buscar, e para salvar o que tinha se perdido.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK19.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(5, $story${"id":"biblia-livre-luk-10-38-42","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Marta e Maria recebem Jesus · Lucas 10:38–42"},"summary":{"pt":"38. E aconteceu que eles, enquanto eles caminhavam, ele entrou em uma aldeia; e uma certa mulher, de nome Marta, o recebeu em sua casa.\n\n39. E esta tinha uma irmã, chamada Maria, a qual, sentando-se também aos pés de Jesus, ouvia sua palavra."},"body":{"pt":"38. E aconteceu que eles, enquanto eles caminhavam, ele entrou em uma aldeia; e uma certa mulher, de nome Marta, o recebeu em sua casa.\n\n39. E esta tinha uma irmã, chamada Maria, a qual, sentando-se também aos pés de Jesus, ouvia sua palavra.\n\n40. Marta, porém, ficava muito ocupada com muitos serviços; e ela, vindo, disse: Senhor, não te importas que minha irmã me deixe sozinha para servir? Dize a ela, pois, que me ajude.\n\n41. E respondendo Jesus, disse-lhe: Marta, Marta, tu és preocupada com muitas coisas, e perturbada por elas;\n\n42. Mas somente uma coisa é necessária. E Maria escolheu a parte boa, a qual não lhe será tirada.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK10.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(6, $story${"id":"biblia-livre-luk-8-22-25","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus acalma a tempestade · Lucas 8:22–25"},"summary":{"pt":"22. E aconteceu, num daqueles dias, que Jesus entrou em um barco com seus discípulos, e disse-lhes: “Passemos para o outro lado do lago”. E partiram.\n\n23. E enquanto navegavam, Jesus adormeceu; então desceu uma tempestade de vento no lago, e enchiam-se de água , e estavam em perigo."},"body":{"pt":"22. E aconteceu, num daqueles dias, que Jesus entrou em um barco com seus discípulos, e disse-lhes: “Passemos para o outro lado do lago”. E partiram.\n\n23. E enquanto navegavam, Jesus adormeceu; então desceu uma tempestade de vento no lago, e enchiam-se de água , e estavam em perigo.\n\n24. Então se aproximaram dele e o despertaram, dizendo: “Mestre, Mestre, estamos perecendo!” E ele se levantou, repreendeu o vento e as ondas da água; e pararam, e fez-se bonança.\n\n25. E disse-lhes: “Onde está a vossa fé?” Mas eles, temendo, admiravam-se, e diziam uns aos outros: “Quem é este, que manda até aos ventos, e à água, e lhe obedecem?”\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK08.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(7, $story${"id":"biblia-livre-luk-7-11-17","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus encontra uma mãe em Naim · Lucas 7:11–17"},"summary":{"pt":"11. E aconteceu no dia seguinte, que Jesus ia a uma cidade chamada Naim, e com ele iam muitos de seus discípulos e uma grande multidão.\n\n12. E quando chegou perto da porta da cidade, eis que levavam um defunto, filho único de sua mãe, que era viúva; e com ela ia grande multidão da cidade."},"body":{"pt":"11. E aconteceu no dia seguinte, que Jesus ia a uma cidade chamada Naim, e com ele iam muitos de seus discípulos e uma grande multidão.\n\n12. E quando chegou perto da porta da cidade, eis que levavam um defunto, filho único de sua mãe, que era viúva; e com ela ia grande multidão da cidade.\n\n13. Quando o Senhor a viu, comoveu-se de intima compaixão por ela, e disse-lhe: Não chores.\n\n14. Então se aproximou, tocou o caixão (e os que a levavam, pararam), e disse: Jovem, a ti eu digo: levanta-te.\n\n15. E o defunto se sentou e começou a falar; e ele o entregou à sua mãe.\n\n16. Todos se encheram de temor, e glorificavam a Deus, dizendo: “Um grande profeta se levantou entre nós, e Deus visitou o seu povo!”\n\n17. E essa sua fama correu por toda a Judeia, e por toda a região em redor.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK07.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(8, $story${"id":"biblia-livre-luk-8-40-56","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"A filha de Jairo · Lucas 8:40–56"},"summary":{"pt":"40. E aconteceu que, quando Jesus voltou, a multidão o recebeu; porque todos o estavam esperando.\n\n41. E eis que chegou um homem, cujo nome era Jairo, e era chefe da sinagoga. Então ele se prostrou aos pés de Jesus e rogou-lhe que entrasse em sua casa;"},"body":{"pt":"40. E aconteceu que, quando Jesus voltou, a multidão o recebeu; porque todos o estavam esperando.\n\n41. E eis que chegou um homem, cujo nome era Jairo, e era chefe da sinagoga. Então ele se prostrou aos pés de Jesus e rogou-lhe que entrasse em sua casa;\n\n42. porque tinha uma filha única, com doze anos de idade, que estava a ponto de morrer. E enquanto ele ia, as multidões o apertavam.\n\n43. E uma mulher que tinha um fluxo de sangue, havia doze anos, e já tinha gastado todos os seus pertences com médicos, e não pôde ser curada por nenhum.\n\n44. Ela se aproximou de Jesus por detrás, e tocou a borda de sua roupa; e logo o fluxo de seu sangue parou.\n\n45. E Jesus disse: “Quem me tocou?” Enquanto todos negavam, disse Pedro e os que com ele estavam: Mestre, as multidões te apertam e empurram, e dizes: Quem me tocou?\n\n46. Jesus disse: “Alguém me tocou, pois sei que poder saiu de mim”.\n\n47. Então a mulher, vendo que não podia se esconder, veio tremendo, prostrou-se diante dele, e declarou-lhe diante de todo o povo a causa por que o havia tocado, e como logo havia sarado.\n\n48. E ele lhe disse: “Tem bom ânimo, filha; a tua fé te sarou; vai em paz”.\n\n49. Estando ele ainda falando, veio um da casa do chefe da sinagoga, que lhe disse: “Tua filha já está morta, não incomodes o Mestre.”\n\n50. Porém quando Jesus o ouviu, respondeu-lhe: “Não temas; crê somente, e ela será curada”.\n\n51. E quando entrou na casa, a ninguém deixou entrar, a não ser a Pedro, Tiago, João, e ao pai e à mãe da menina.\n\n52. E todos choravam e lamentavam por ela; mas ele disse: “Não choreis; ela não está morta, mas dorme”.\n\n53. E riam dele, porque sabiam que estava morta.\n\n54. Porém ele, depois de expulsá-los todos, segurou a mão dela e clamou: “Levanta-te, menina”.\n\n55. Então seu espírito voltou, e ela logo se levantou; e Jesus mandou que dessem de comer a ela.\n\n56. E seus pais ficaram maravilhados, mas ele lhes mandou que a ninguém dissessem o que havia acontecido.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK08.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(9, $story${"id":"biblia-livre-luk-24-13-35","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"O caminho de Emaús · Lucas 24:13–35"},"summary":{"pt":"13. E eis que dois deles iam naquele mesmo dia a uma aldeia, cujo nome era Emaús, que estava a sessenta estádios de distância de Jerusalém.\n\n14. E iam falando entre si de todas aquelas coisas que tinham acontecido."},"body":{"pt":"13. E eis que dois deles iam naquele mesmo dia a uma aldeia, cujo nome era Emaús, que estava a sessenta estádios de distância de Jerusalém.\n\n14. E iam falando entre si de todas aquelas coisas que tinham acontecido.\n\n15. E aconteceu que, enquanto eles estavam conversando entre si, e perguntando um ao outro, Jesus se aproximou, e foi junto deles.\n\n16. Mas seus olhos foram retidos, para que não o reconhecessem.\n\n17. E disse-lhes: Que conversas são essas, que vós discutis enquanto andam, e ficais tristes?\n\n18. E um deles ,cujo nome era Cleofas, respondendo-o, disse-lhe: És tu o único viajante em Jerusalém que não sabe as coisas que nela tem acontecido nestes dias?\n\n19. E ele lhes disse: Quais?E eles lhe disseram: As sobre Jesus de Nazaré, a qual foi um homem profeta, poderoso em obras e em palavras, diante de Deus, e de todo o povo.\n\n20. E como os chefes dos sacerdotes, e nossos líderes o entregaram à condenação de morte, e o crucificaram.\n\n21. E nós esperávamos que ele fosse aquele que libertar a Israel; porém além de tudo isto, hoje é o terceiro dia desde que estas coisas aconteceram.\n\n22. Ainda que também algumas mulheres dentre nós nos deixaram surpresos, as quais de madrugada foram ao sepulcro;\n\n23. E não achando seu corpo, vieram, dizendo que também tinham visto uma aparição de anjos, que disseram que ele vive.\n\n24. E alguns do que estão conosco foram ao sepulcro, e o acharam assim como as mulheres tinham dito; porém não o viram.\n\n25. E ele lhes disse: Ó tolos, e que demoram no coração para crerem em tudo o que os profetas falaram!\n\n26. Por acaso não era necessário que o Cristo sofresse estas coisas, e então entrar em sua glória?\n\n27. E começando de Moisés, e por todos os profetas, lhes declarava em todas as Escrituras o que estava escrito sobre ele.\n\n28. E chegaram à aldeia para onde estavam indo; e ele agiu como se fosse para um lugar mais distante.\n\n29. E eles lhe rogaram, dizendo: Fica conosco, porque já é tarde, e o dia está entardecendo;E ele entrou para ficar com eles.\n\n30. E aconteceu que, estando sentado com eles à mesa ,tomou o pão, o benzeu, o partiu, e o deu a eles.\n\n31. E os olhos deles se abriram, e o reconheceram, e ele lhes desapareceu.\n\n32. E diziam um ao outro: Por acaso não estava nosso coração ardendo em nós, quando ele falava conosco pelo caminho, e quando nos desvendava as Escrituras?\n\n33. E levantando-se na mesma hora, voltaram para Jerusalém, e acharam reunidos aos onze, e aos que estavam com eles,\n\n34. Que diziam: Verdadeiramente o Senhor ressuscitou, e já apareceu a Simão.\n\n35. E eles contaram as coisas que lhes aconteceram no caminho; e como foi reconhecido por eles quando partiu o pão.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK24.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(10, $story${"id":"biblia-livre-luk-5-1-11","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"A pesca no lago · Lucas 5:1–11"},"summary":{"pt":"1. E aconteceu que as multidões o comprimiam para ouvir a palavra de Deus, quando ele estava junto ao lago de Genesaré.\n\n2. Então ele viu dois barcos que estavam próximos da margem do lago, e os pescadores haviam descido deles, e estavam lavando as redes."},"body":{"pt":"1. E aconteceu que as multidões o comprimiam para ouvir a palavra de Deus, quando ele estava junto ao lago de Genesaré.\n\n2. Então ele viu dois barcos que estavam próximos da margem do lago, e os pescadores haviam descido deles, e estavam lavando as redes.\n\n3. Ele entrou num daqueles barcos, que era o de Simão, e lhe pediu que o afastasse um pouco da terra. Depois se sentou, e do barco ensinou às multidões.\n\n4. Quando acabou de falar, disse a Simão: Vai à água profunda, e lançai as vossas redes para pescar.\n\n5. Simão lhe respondeu: Mestre, trabalhamos toda a noite, mas nada pegamos; mas pela tua palavra lançarei a rede.\n\n6. Eles fizeram assim, e recolheram grande quantidade de peixes, e sua rede estava se rompendo.\n\n7. Então acenaram aos companheiros que estavam no outro barco, para que viessem os ajudar. Vieram, e encheram ambos os barcos, de tal maneira que quase afundavam.\n\n8. Quando Simão Pedro viuisso , prostrou-se aos pés de Jesus, dizendo: Afasta-te de mim, Senhor, porque sou um homem pecador.\n\n9. Pois ele estava cheio de espanto, como todos os que estavam com ele, por causa da coleta de peixes que haviam feito.\n\n10. E semelhantemente, também, Tiago e João, filhos de Zebedeu, que eram colegas de Simão. E Jesus disse a Simão: Não temas, de agora em diante pescarás gente.\n\n11. Eles levaram os barcos para a terra, deixaram tudo, e o seguiram.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/LUK05.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(11, $story${"id":"biblia-livre-jhn-2-1-11","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"As bodas em Caná · João 2:1–11"},"summary":{"pt":"1. E no terceiro dia houve um casamento em Caná da Galileia; e a mãe de Jesus estava ali.\n\n2. E também Jesus foi convidado com seus discípulos ao casamento."},"body":{"pt":"1. E no terceiro dia houve um casamento em Caná da Galileia; e a mãe de Jesus estava ali.\n\n2. E também Jesus foi convidado com seus discípulos ao casamento.\n\n3. E tendo faltado vinho, a mãe de Jesus lhe disse: Não têm vinho.\n\n4. Jesus lhe disse: O que eu tenho contigo, mulher? A minha hora ainda não chegou.\n\n5. Sua mãe disse aos serventes: Fazei tudo quanto ele vos disser.\n\n6. E estavam ali postos seis vasos de pedra, conforme à purificação dos judeus, em cada uma cabiam duas ou três metretas. )\n\n7. Disse-lhes Jesus: Enchei estes vasos com água. E encheram-nas até encima.\n\n8. E disse-lhes: Agora tirai, e a levai ao mestre de cerimônia. Então levaram.\n\n9. E quando o mestre de cerimônia experimentou a água feita vinho (sem saber de onde era, porém os serventes que haviam tirado a água sabiam), o mestre de cerimônia chamou o noivo,\n\n10. E disse-lhe: Todos põem primeiro o vinho bom, e quando os convidados já estão bêbados, então se dá o pior; porém tu guardaste o bom vinho até agora.\n\n11. Este princípio de sinais Jesus fez em Caná da Galileia, e manifestou sua glória; e seus discípulos creram nele.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JHN02.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(12, $story${"id":"biblia-livre-jhn-4-5-26","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus e a mulher junto ao poço · João 4:5–26"},"summary":{"pt":"5. Veio pois a uma cidade de Samaria, chamada Sicar, junto à propriedade que Jacó deu a seu filho José.\n\n6. E ali estava a fonte de Jacó. Então Jesus, cansado do caminho, sentou-se assim junto à fonte; era isto quase à hora sexta."},"body":{"pt":"5. Veio pois a uma cidade de Samaria, chamada Sicar, junto à propriedade que Jacó deu a seu filho José.\n\n6. E ali estava a fonte de Jacó. Então Jesus, cansado do caminho, sentou-se assim junto à fonte; era isto quase à hora sexta.\n\n7. Veio uma mulher de Samaria para tirar água; Disse-lhe Jesus: Dá-me de beber.\n\n8. (Porque seus discípulos haviam ido à cidade para a comprar de comer).\n\n9. Disse-lhe pois a mulher samaritana: Como, sendo tu judeu, me pedes de beber, que sou mulher samaritana? (Porque os judeus não se comunicam com o samaritanos.)\n\n10. Respondeu Jesus, e disse-lhe: Se tu conhecesses o dom de Deus, e quem é o que te diz: Dá-me de beber, tu lhe pedirias, e ele te daria água viva.\n\n11. Disse a mulher: Senhor, tu não tens com que a tirar, e o poço é fundo; de onde pois tens a água viva?\n\n12. És tu maior que nosso pai Jacó, que nos deu o poço? E ele mesmo dele bebeu, e seus filhos, e seu gado?\n\n13. Jesus respondeu, e disse-lhe: Todo aquele que beber desta água voltará a ter sede;\n\n14. Porém aquele que beber da água que eu lhe der, para sempre não terá sede, mas a água que eu lhe der se fará nele fonte de água, que salte para vida eterna.\n\n15. Disse-lhe a mulher: Senhor, dá-me desta água, para que eu não tenha mais sede, nem venha aqui para tirar.\n\n16. Disse-lhe Jesus: Vai, chama a teu marido, e vem cá.\n\n17. A mulher respondeu, e disse: Não tenho marido. Disse-lhe Jesus: Bem disseste: Marido não tenho.\n\n18. Porque cinco maridos tiveste, e o que agora tens não é teu marido; isto com verdade disseste.\n\n19. Disse-lhe a mulher: Senhor, vejo que és profeta.\n\n20. Nossos pais adoraram neste monte, e vós dizeis que em Jerusalém é o lugar onde se deve adorar.\n\n21. Disse-lhe Jesus: Mulher, crê em mim, que a hora vem, quando nem neste monte, nem em Jerusalém, adorareis ao Pai.\n\n22. Vós adorais o que não sabeis; nós adoramos o que sabemos, porque a salvação vem dos judeus.\n\n23. Porém a hora vem, e agora é, quando os verdadeiros adoradores adorarão ao Pai em espírito e em verdade; porque também o Pai busca a tais que o adorem.\n\n24. Deus é Espírito, e os que o adoram devem adorá -lo em espírito e em verdade.\n\n25. Disse-lhe a mulher: Eu sei que o Messias vem (que se chama o Cristo); quando ele vier, todas as coisas nos anunciará.\n\n26. Disse-lhe Jesus: Eu sou o que contigo falo.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JHN04.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(13, $story${"id":"biblia-livre-jhn-6-1-14","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Os pães e os peixes · João 6:1–14"},"summary":{"pt":"1. Depois disto Jesus partiu para a outro lado do mar da Galileia, que é o de Tibérias.\n\n2. E uma grande multidão o seguia, porque viam seus sinais que ele fazia nos enfermos."},"body":{"pt":"1. Depois disto Jesus partiu para a outro lado do mar da Galileia, que é o de Tibérias.\n\n2. E uma grande multidão o seguia, porque viam seus sinais que ele fazia nos enfermos.\n\n3. E subiu Jesus ao monte, e sentou-se ali com seus discípulos.\n\n4. E já a Páscoa, a festa dos judeus, estava perto.\n\n5. Levantando pois Jesus os olhos, e vendo que uma grande multidão vinha a ele, disse a Filipe: De onde comparemos pães, para que estes comam?\n\n6. (Mas ele disse isto para o testar; pois ele bem sabia o que havia de fazer.)\n\n7. Respondeu-lhe Filipe: Duzentos dinheiros de pão não lhes bastarão, para que cada um deles tome um pouco.\n\n8. Disse-lhe um de seus discípulos, André, o irmão de Simão Pedro:\n\n9. Um menino está aqui que tem cinco pães de cevada e dois peixinhos; mas que é isto entre tantos?\n\n10. E disse Jesus: Fazei sentar as pessoas; e havia muita erva naquele lugar. Sentaram-se, pois, os homens, em número de cinco mil.\n\n11. E tomou Jesus os pães, e havendo dado graças, repartiu-os aos discípulos, e os discípulos aos que estavam sentados, semelhantemente também dos peixes, quanto queriam.\n\n12. E quando já estiveram fartos, disse ele a seus discípulos: Recolhei os pedaços que sobraram, para que nada se perca.\n\n13. Então eles os recolheram, e encheram doze cestos de pedaços dos cinco pães de cevada, que sobraram aos que tinham comido.\n\n14. Vendo, pois, aquelas pessoas o sinal que Jesus fizera, disseram: Este é verdadeiramente o Profeta que havia de vir ao mundo!\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JHN06.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(14, $story${"id":"biblia-livre-jhn-9-1-12","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"O homem que nasceu cego · João 9:1–12"},"summary":{"pt":"1. E indo Jesus passando, viu a um homem cego desde o nascimento.\n\n2. E seus discípulos lhe perguntaram, dizendo: Rabi, quem pecou? Este, ou seus pais, para que nascesse cego?"},"body":{"pt":"1. E indo Jesus passando, viu a um homem cego desde o nascimento.\n\n2. E seus discípulos lhe perguntaram, dizendo: Rabi, quem pecou? Este, ou seus pais, para que nascesse cego?\n\n3. Respondeu Jesus: Nem este pecou, nem seus pais; mas sim para que as obras de Deus nele se manifestem.\n\n4. A mim me convém trabalhar as obras daquele que me enviou, enquanto é dia; a noite vem, quando ninguém pode trabalhar.\n\n5. Enquanto estiver no mundo, eu sou a luz do mundo.\n\n6. Dito isto, cuspiu em terra, e fez lama do cuspe, e untou com aquela lama os olhos do cego.\n\n7. E disse-lhe: Vai, lava-te no tanque de Siloé (que se traduz Enviado). Foi pois, e lavou-se; e voltou vendo.\n\n8. Então os vizinhos, e os que de antes o viram que era cego, diziam: Não é este aquele que estava sentado, e mendigava?\n\n9. Outros diziam: É este. E outros: Parece-se com ele. Ele dizia: Sou eu.\n\n10. Então lhe diziam: Como teus olhos se abriram?\n\n11. Respondeu ele, e disse: Aquele homem chamado Jesus fez lama, untou meus olhos, e me disse: Vai ao tanque de Siloé, e lava-te. E fui, e me lavei, e vi.\n\n12. Disseram-lhe, pois: Onde ele está? Disse ele: Não sei.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JHN09.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(15, $story${"id":"biblia-livre-jhn-11-17-44","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus e Lázaro · João 11:17–44"},"summary":{"pt":"17. Vindo pois Jesus, encontrou que já havia quatro dias que estava na sepultura.\n\n18. (E Betânia era como quase quinze estádios de Jerusalém)."},"body":{"pt":"17. Vindo pois Jesus, encontrou que já havia quatro dias que estava na sepultura.\n\n18. (E Betânia era como quase quinze estádios de Jerusalém).\n\n19. E muitos dos judeus tinham vindo até Marta e Maria, para consolá-las por seu irmão.\n\n20. Ouvindo pois Marta que Jesus vinha, saiu-lhe ao encontro; mas Maria ficou sentada em casa.\n\n21. Disse pois Marta a Jesus: Senhor, se tu estivesses aqui, meu irmão não teria morrido.\n\n22. Porém também sei agora, que tudo quanto pedires a Deus, Deus o dará a ti.\n\n23. Disse-lhe Jesus: Teu irmão ressuscitará.\n\n24. Marta lhe disse: Eu sei que ele ressuscitará, na ressurreição, no último dia.\n\n25. Disse-lhe Jesus: Eu sou a ressurreição, e a vida; quem crê em mim, ainda que esteja morto, viverá.\n\n26. E todo aquele que vive, e crê em mim, para sempre não morrerá. Crês nisto?\n\n27. Disse-lhe ela: Sim, Senhor; já cri que tu és o Cristo, o Filho de Deus, que viria ao mundo.\n\n28. E dito isto, ela se foi, e chamou em segredo a Maria, sua irmã, dizendo: Aqui está o Mestre, e ele te chama.\n\n29. Ouvindo ela isto ,logo se levantou, e foi até ele.\n\n30. (Porque Jesus ainda não havia chegado à aldeia; mas estava no lugar onde Marta lhe saíra ao encontro).\n\n31. Vendo pois os judeus que com ela estavam em casa, e a consolavam, que Maria com pressa se levantara, e saíra, seguiram-na, dizendo: Ela vai para a sepultura, para chorar lá.\n\n32. Vindo pois Maria aonde Jesus estava, e vendo-o, caiu a seus pés, dizendo-lhe: Senhor, se tu estivesses aqui, meu irmão não teria morrido.\n\n33. Quando Jesus a viu chorar, e aos judeus, que vinham chorando com ela, comoveu-se em espírito, e ficou perturbado.\n\n34. E disse: Onde o pusestes? Disseram-lhe: Senhor, vem, e vê.\n\n35. Jesus chorou.\n\n36. Disseram pois os Judeus: Vede como ele o amava!\n\n37. E alguns deles disseram: Não podia este, que abriu os olhos ao cego, ter feito também que este não morresse?\n\n38. Comovendo-se pois Jesus outra vez em si mesmo, veio à sepultura; e era esta uma caverna, e estava uma pedra posta sobre ela.\n\n39. Disse Jesus: Tirai a pedra. Marta, a irmã do morto, disse-lhe: Senhor, já cheira mal, porque já é de quatro dias.\n\n40. Jesus disse-lhe: Não te disse, que se creres, verás a glória de Deus?\n\n41. Tiraram, pois, a pedra de onde o morto jazia. E Jesus levantou os olhos para cima, e disse: Pai, graças te dou, porque me tens ouvido.\n\n42. Porém eu bem sabia que sempre me ouves; mas por causa da multidão, que está ao redor, assim disse; para que creiam que tu me enviaste.\n\n43. E havendo dito isto, clamou com grande voz: Lázaro, sai fora.\n\n44. E o que estava morto saiu, com as mãos e os pés atados, e seu rosto envolto em um lenço. Disse-lhes Jesus: Desatai-o, e deixai-o ir.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JHN11.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(16, $story${"id":"biblia-livre-jhn-20-11-18","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Maria Madalena no jardim · João 20:11–18"},"summary":{"pt":"11. E Maria estava fora chorando junto ao sepulcro. Estando ela pois chorando, abaixou-se para ver o sepulcro.\n\n12. E viu a dois anjos vestidos de branco, sentados um à cabeceira, e o outro aos pés, onde estava posto o corpo de Jesus."},"body":{"pt":"11. E Maria estava fora chorando junto ao sepulcro. Estando ela pois chorando, abaixou-se para ver o sepulcro.\n\n12. E viu a dois anjos vestidos de branco, sentados um à cabeceira, e o outro aos pés, onde estava posto o corpo de Jesus.\n\n13. E disseram-lhe eles: Mulher, por que choras? Disse-lhes ela: Porque levaram a meu Senhor, e não sei onde o puseram.\n\n14. E havendo dito isto, virou-se para trás, e viu Jesus em pé, e não sabia que era Jesus.\n\n15. Disse-lhe Jesus: Mulher, por que choras? A quem buscas? Ela, pensando que era o jardineiro, disse-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei.\n\n16. Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe: Rabôni! (que quer dizer Mestre).\n\n17. Disse-lhe Jesus: Não me toques; porque ainda não subi para o meu Pai; porém vai a meus irmãos, e dize- lhes: Subo para meu Pai, e para vosso Pai; para meu Deus, e para vosso Deus.\n\n18. Veio Maria Madalena, e anunciou aos discípulos, que vira ao Senhor, e que estas coisas lhe dissera.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JHN20.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(17, $story${"id":"biblia-livre-mat-14-22-33","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus caminha sobre as águas · Mateus 14:22–33"},"summary":{"pt":"22. E logo Jesus mandou os seus discípulos entrarem no barco, e que fossem adiante dele para a outra margem, enquanto ele despedia as multidões.\n\n23. Depois de despedir as multidões, subiu ao monte, à parte, para orar. Tendo chegado a noite, ele estava ali sozinho."},"body":{"pt":"22. E logo Jesus mandou os seus discípulos entrarem no barco, e que fossem adiante dele para a outra margem, enquanto ele despedia as multidões.\n\n23. Depois de despedir as multidões, subiu ao monte, à parte, para orar. Tendo chegado a noite, ele estava ali sozinho.\n\n24. E o barco já estava no meio do mar, atormentado pelas ondas, porque o vento era contrário.\n\n25. Mas à quarta vigília da noite Jesus foi até eles, andando sobre o mar.\n\n26. Quando os discípulos o viram andar sobre o mar, apavoraram-se, dizendo: É um fantasma! E gritaram de medo.\n\n27. Mas Jesus logo lhes falou, dizendo: Tende coragem! Sou eu, não tenhais medo.\n\n28. E Pedro lhe respondeu, dizendo: Senhor, se és tu, manda-me vir a ti sobre as águas.\n\n29. E ele disse: Vem. Então Pedro desceu do barco e andou sobre as águas, para vir em direção a Jesus.\n\n30. Mas quando viu o vento forte, teve medo; e começando a afundar, gritou: Senhor, salva-me!\n\n31. Imediatamente Jesus estendeu a mão, segurou-o, e disse-lhe: Homem de pouca fé, por que duvidaste?\n\n32. E quando subiram no barco, o vento se aquietou.\n\n33. Então os que estavam no barco vieram e o adoraram, dizendo: Verdadeiramente tu és o Filho de Deus.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/MAT14.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(18, $story${"id":"biblia-livre-mat-7-24-27","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"A casa construída sobre a rocha · Mateus 7:24–27"},"summary":{"pt":"24. Portanto todo o que ouve estas minhas palavras e as pratica, eu o compararei ao homem prudente, que construiu sua casa sobre a rocha.\n\n25. E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela não caiu, porque estava fundada sobre a rocha."},"body":{"pt":"24. Portanto todo o que ouve estas minhas palavras e as pratica, eu o compararei ao homem prudente, que construiu sua casa sobre a rocha.\n\n25. E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela não caiu, porque estava fundada sobre a rocha.\n\n26. Porém todo o que ouve estas minhas palavras e não as pratica, eu o compararei ao homem tolo, que construiu sua casa sobre a areia.\n\n27. E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela caiu, e sua queda foi grande.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/MAT07.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(19, $story${"id":"biblia-livre-mrk-10-13-16","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jesus acolhe as crianças · Marcos 10:13–16"},"summary":{"pt":"13. E lhe traziam crianças para que ele as tocasse, mas os discípulos repreendiam aos que as traziam.\n\n14. Porém Jesus, vendo, indignou-se, e lhe disse: Deixai vir as crianças a mim, e não as impeçais; porque delas é o Reino de Deus."},"body":{"pt":"13. E lhe traziam crianças para que ele as tocasse, mas os discípulos repreendiam aos que as traziam.\n\n14. Porém Jesus, vendo, indignou-se, e lhe disse: Deixai vir as crianças a mim, e não as impeçais; porque delas é o Reino de Deus.\n\n15. Em verdade vos digo, que qualquer um que não receber o Reino de Deus como criança, em maneira nenhuma nele entrará.\n\n16. Então, tomando-as entre seus braços, e pondo as mãos sobre elas, ele as abençoou.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/MRK10.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(20, $story${"id":"biblia-livre-mrk-10-46-52","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Bartimeu à beira do caminho · Marcos 10:46–52"},"summary":{"pt":"46. E vieram a Jericó. E saindo ele, e seus discípulos, e uma grande multidão de Jericó, estava Bartimeu, um cego, filho de Timeu, sentado junto ao caminho.\n\n47. E ouvindo que era Jesus o nazareno, começou a clamar, e a dizer: Jesus, Filho de Davi! Tem misericórdia de mim!"},"body":{"pt":"46. E vieram a Jericó. E saindo ele, e seus discípulos, e uma grande multidão de Jericó, estava Bartimeu, um cego, filho de Timeu, sentado junto ao caminho.\n\n47. E ouvindo que era Jesus o nazareno, começou a clamar, e a dizer: Jesus, Filho de Davi! Tem misericórdia de mim!\n\n48. E muitos o repreendiam, para que se calasse; mas ele clamava ainda mais: Filho de Davi! Tem misericórdia de mim!\n\n49. Jesus parou, e disse que o chamassem. Então chamaram ao cego, dizendo-lhe: Tem bom ânimo, levanta-te, ele está te chamando.\n\n50. Então ele lançou sua capa, levantou-se, e veio a Jesus.\n\n51. Jesus, lhe perguntou: Que queres que eu te faça? E o cego lhe disse: Mestre, que eu veja.\n\n52. Jesus lhe disse: Vai; a tua fé te salvou. E logo consegiu ver. Então seguiu Jesus pelo caminho.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/MRK10.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(21, $story${"id":"biblia-livre-mrk-12-41-44","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"A oferta da viúva · Marcos 12:41–44"},"summary":{"pt":"41. Quando Jesus estava sentado de frente à arca do tesouro, observava como a multidão lançava dinheiro na arca do tesouro; e muitos ricos lançavam muito.\n\n42. E uma pobre viúva veio, e lançou duas pequenas moedas, de pouco valor."},"body":{"pt":"41. Quando Jesus estava sentado de frente à arca do tesouro, observava como a multidão lançava dinheiro na arca do tesouro; e muitos ricos lançavam muito.\n\n42. E uma pobre viúva veio, e lançou duas pequenas moedas, de pouco valor.\n\n43. Então Jesus chamou a si os seus discípulos, e disse-lhes: Em verdade vos digo que esta pobre viúva lançou mais que todos os que lançaram na arca do tesouro;\n\n44. Porque todos lançaram daquilo que lhes sobra; mas esta, da sua pobreza lançou tudo o que tinha, todo o seu sustento.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/MRK12.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(22, $story${"id":"biblia-livre-act-2-1-13","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"O dia de Pentecostes · Atos 2:1–13"},"summary":{"pt":"1. E ao se cumprir o dia de Pentecostes, estavam todos concordando no mesmo lugar.\n\n2. E de repente houve um ruído do céu, como de um vento forte e violento, e encheu toda a casa onde eles estavam sentados."},"body":{"pt":"1. E ao se cumprir o dia de Pentecostes, estavam todos concordando no mesmo lugar.\n\n2. E de repente houve um ruído do céu, como de um vento forte e violento, e encheu toda a casa onde eles estavam sentados.\n\n3. E foram vistas por eles línguas repartidas como que de fogo, e se pôs sobre cada um deles.\n\n4. E eles foram todos cheios do Espírito Santo, e começaram a falar em outras línguas, conforme o Espírito lhes dava a discursarem.\n\n5. E havia judeus que estavam morando em Jerusalém, homens devotos, de toda nação abaixo do céu.\n\n6. E acontecendo esta voz, ajuntou-se a multidão; e ela estava confusa, porque cada um os ouvia falar em sua própria língua.\n\n7. E todos estavam admirados, e se maravilhavam, dizendo uns aos outros: Ora, estes que estão falando, não são todos eles galileus?\n\n8. E como nós ouvimos cada um deles em nossa própria língua, na qual nascemos?\n\n9. Partos, Medos, Elamitas, os habitantes da Mesopotâmia, da Judeia, Capadócia, Ponto, Ásia,\n\n10. Frígia, Panfília, Egito e regiões da Líbia perto de Cirene, e romanos estrangeiros, tanto judeus como prosélitos,\n\n11. Cretenses e Árabes, os ouvimos em nossas próprias línguas eles falarem das grandezas de Deus.\n\n12. E todos estavam admirados e confusos, dizendo uns aos outros: O que isso quer dizer?\n\n13. E outros, ridicularizando, diziam: Eles estão cheios de vinho doce.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/ACT02.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(23, $story${"id":"biblia-livre-act-16-25-34","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Paulo e Silas na prisão · Atos 16:25–34"},"summary":{"pt":"25. E perto da meia-noite, Paulo e Silas estavam orando, e cantando hinos a Deus; e os outros presos os escutavam.\n\n26. E de repente houve um terremoto tão grande que os alicerces da prisão se moviam; e logo todas as portas se abriram, e todas as correntes que prendiam a todos se soltaram."},"body":{"pt":"25. E perto da meia-noite, Paulo e Silas estavam orando, e cantando hinos a Deus; e os outros presos os escutavam.\n\n26. E de repente houve um terremoto tão grande que os alicerces da prisão se moviam; e logo todas as portas se abriram, e todas as correntes que prendiam a todos se soltaram.\n\n27. E o carcereiro, tendo acordado e visto abertas todas as portas da prisão; puxou a espada, e estava a ponto de se matar, pensando que os presos tinham fugido.\n\n28. Mas Paulo clamou em alta voz, dizendo: Não te faças nenhum mal, porque todos nós estamos aqui.\n\n29. E tendo pedido luzes, saltou para dentro, e termendo muito, ele se prostrou diante de Paulo e Silas.\n\n30. E levando-os para fora, disse: Senhores, o que me é necessário fazer para eu me salvar?\n\n31. E eles lhe disseram: Crê no Senhor Jesus Cristo, e serás salvo, tu e a tua casa.\n\n32. E lhe falaram da palavra do Senhor, e a todos os que estavam em sua casa.\n\n33. E ele, tomando-os consigo, naquela mesma hora da noite, lavou -lhes as feridas dos açoites, e logo foi batizado, ele e todos os seus.\n\n34. E tendo os levado a sua casa, pôs comida diante deles à mesa; e alegrou-se muito, tendo crido em Deus com toda a sua casa.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/ACT16.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(24, $story${"id":"biblia-livre-act-9-36-42","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"A história de Tabita · Atos 9:36–42"},"summary":{"pt":"36. E havia em Jope uma certa discípula, de nome Tabita, que traduzido se diz Dorcas. Esta estava cheia de boas obras e doações que ela fazia aos necessitados .\n\n37. E aconteceu naqueles dias, que tendo ela ficado doente, morreu; e tendo a lavado, puseram-na no compartimento superior."},"body":{"pt":"36. E havia em Jope uma certa discípula, de nome Tabita, que traduzido se diz Dorcas. Esta estava cheia de boas obras e doações que ela fazia aos necessitados .\n\n37. E aconteceu naqueles dias, que tendo ela ficado doente, morreu; e tendo a lavado, puseram-na no compartimento superior.\n\n38. E como Lida era perto de Jope, os discípulos, ao ouvirem que Pedro estava ali, mandaram-lhe dois homens, rogando -lhe que não demorasse a vir a eles.\n\n39. E Pedro, tendo se levantado, foi com eles; o qual chegou, e o levaram ao compartimento superior, e todas as viúvas o rodearam, chorando, e mostrando -lhe as túnicas e roupas que Dorcas tinha feito quando estava com elas.\n\n40. Mas Pedro, pondo para fora a todas; pôs-se de joelhos, e orou; e virando-se para o corpo, disse: Tabita, levanta-te;E ela abriu seus olhos, e vendo a Pedro, sentou-se.\n\n41. E ele, dando-lhe a mão, levantou-a; e tendo chamado aos santos, e às viúvas, apresentou-a viva.\n\n42. E isto ficou conhecido por toda Jope, e muitos creram no Senhor.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/ACT09.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(25, $story${"id":"biblia-livre-rut-1-6-18","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Rute e Noemi · Rute 1:6–18"},"summary":{"pt":"6. Então se levantou com suas noras, e voltou-se dos campos de Moabe: porque ouviu no campo de Moabe que o SENHOR havia visitado a seu povo para dar-lhes pão.\n\n7. Saiu, pois, do lugar de onde havia estado, e com ela suas duas noras, e começaram em caminhar para voltar-se à terra de Judá."},"body":{"pt":"6. Então se levantou com suas noras, e voltou-se dos campos de Moabe: porque ouviu no campo de Moabe que o SENHOR havia visitado a seu povo para dar-lhes pão.\n\n7. Saiu, pois, do lugar de onde havia estado, e com ela suas duas noras, e começaram em caminhar para voltar-se à terra de Judá.\n\n8. E Noemi disse a suas duas noras: Andai, voltai-vos cada uma à casa de sua mãe: o SENHOR faça convosco misericórdia, como a fizestes com os mortos e comigo.\n\n9. Dê-vos o SENHOR que acheis descanso, cada uma em casa de seu marido: beijou-as logo, e elas choraram a voz em grito.\n\n10. E disseram-lhe: Certamente nós voltaremos contigo a teu povo.\n\n11. E Noemi respondeu: Voltai, filhas minhas; para que ireis comigo? Tenho eu mais filhos no ventre, que possam ser vossos maridos?\n\n12. Voltai, filhas minhas, e ide; que eu já sou velha para ser para me casar com homem. E ainda que dissesse: Tenho esperança; e esta noite me casasse com um homem, e ainda desse à luz filhos;\n\n13. Teríeis vós de esperá-los até que fossem grandes? Ficaríeis vós sem se casar por causa deles? Não, filhas minhas; que maior amargura tenho eu que vós, pois a mão do SENHOR saiu contra mim.\n\n14. Mas elas levantando outra vez sua voz, choraram: e Orfa beijou à sua sogra, mas Rute se ficou com ela.\n\n15. E Noemi disse: Eis que tua cunhada se voltou a seu povo e a seus deuses; volta-te atrás dela.\n\n16. E Rute respondeu: Não me rogues que te deixe, e que me aparte de ti: porque de onde quer que tu fores, irei eu; e de onde quer que viveres, viverei. Teu povo será meu povo, e teu Deus meu Deus.\n\n17. Onde tu morreres, morrerei eu, e ali serei sepultada: assim me faça o SENHOR, e assim me dê, que somente a morte fará separação entre mim e ti.\n\n18. E vendo Noemi que estava tão decidida a ir com ela, deixou de falar-lhe.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/RUT01.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(26, $story${"id":"biblia-livre-gen-45-1-15","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"José reencontra seus irmãos · Gênesis 45:1–15"},"summary":{"pt":"1. Não podia já José se conter diante de todos os que estavam ao seu lado, e clamou: Fazei sair de minha presença a todos. E não ficou ninguém com ele, ao dar-se a conhecer José a seus irmãos.\n\n2. Então se deu a chorar por voz em grito; e ouviram os egípcios, e ouviu também a casa de Faraó."},"body":{"pt":"1. Não podia já José se conter diante de todos os que estavam ao seu lado, e clamou: Fazei sair de minha presença a todos. E não ficou ninguém com ele, ao dar-se a conhecer José a seus irmãos.\n\n2. Então se deu a chorar por voz em grito; e ouviram os egípcios, e ouviu também a casa de Faraó.\n\n3. E disse José a seus irmãos: Eu sou José: vive ainda meu pai? E seus irmãos não puderam lhe responder, porque estavam perturbados diante dele.\n\n4. Então disse José a seus irmãos: Achegai-vos agora a mim. E eles se achegaram. E ele disse: Eu sou José vosso irmão o que vendestes para o Egito.\n\n5. Agora, pois, não vos entristeçais, nem vos pese de haver me vendido aqui; que para preservação de vida me enviou Deus diante de vós:\n\n6. Que já houve dois anos de fome em meio da terra, e ainda restam cinco anos em que nem haverá arada nem colheita.\n\n7. E Deus me enviou adiante de vós, para que vós restásseis na terra, e para vos dar vida por meio de grande salvamento.\n\n8. Assim, pois, não me enviastes vós aqui, mas sim Deus, que me pôs por pai de Faraó, e por senhor de toda sua casa, e por governador de toda a terra do Egito.\n\n9. Apressai-vos, ide a meu pai e dizei-lhe: Assim diz teu filho José: Deus me pôs por senhor de todo Egito; vem a mim, não te detenhas:\n\n10. E habitarás na terra de Gósen, e estarás perto de mim, tu e teus filhos, e os filhos de teus filhos, teus gados e tuas vacas, e tudo o que tens.\n\n11. E ali te alimentarei, pois ainda restam cinco anos de fome, para que não pereças de pobreza tu e tua casa, e tudo o que tens:\n\n12. E eis que, vossos olhos veem, e os olhos de meu irmão Benjamim, que meu boca vos fala.\n\n13. Fareis pois saber a meu pai toda minha glória no Egito, e tudo o que vistes: e apressai-vos, e trazei a meu pai aqui.\n\n14. E lançou-se sobre o pescoço de Benjamim seu irmão, e chorou; e também Benjamim chorou sobre seu pescoço.\n\n15. E beijou a todos os seus irmãos, e chorou sobre eles: e depois seus irmãos falaram com ele.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/GEN45.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(27, $story${"id":"biblia-livre-exo-2-1-10","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Moisés no rio · Êxodo 2:1–10"},"summary":{"pt":"1. Um homem da família de Levi foi, e tomou por mulher uma filha de Levi:\n\n2. A qual concebeu, e deu à luz um filho: e vendo-o que era belo, teve-lhe escondido três meses."},"body":{"pt":"1. Um homem da família de Levi foi, e tomou por mulher uma filha de Levi:\n\n2. A qual concebeu, e deu à luz um filho: e vendo-o que era belo, teve-lhe escondido três meses.\n\n3. Porém não podendo ocultar-lhe mais tempo, tomou uma cesta de juncos, e vedou-a com piche e betume, e colocou nela ao menino, e o pôs entre os juncos à beira do rio:\n\n4. E ficou parada uma irmã sua ao longe, para ver o que lhe aconteceria.\n\n5. E a filha de Faraó desceu a lavar-se ao rio, e passeando suas virgens pela beira do rio, viu ela a cesta entre os juncos, e enviou uma criada sua a que a tomasse.\n\n6. E quando a abriu, viu ao menino; e eis que o menino chorava. E tendo compaixão dele, disse: Dos meninos dos hebreus é este.\n\n7. Então sua irmã disse à filha de Faraó: Irei a chamar-te uma ama das hebreias, para que te crie este menino?\n\n8. E a filha de Faraó respondeu: Vai. Então foi a virgem, e chamou à mãe do menino;\n\n9. À qual disse a filha de Faraó: Leva este menino, e cria-o para mim, e eu te o pagarei. E a mulher tomou ao menino, e o criou.\n\n10. E quando cresceu o menino, ela o trouxe à filha de Faraó, a qual o adotou, e pôs-lhe por nome Moisés, dizendo: Porque das águas o tirei.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/EXO02.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(28, $story${"id":"biblia-livre-jon-3-1-10","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Jonas em Nínive · Jonas 3:1–10"},"summary":{"pt":"1. E a palavra do SENHOR veio pela segunda vez a Jonas, dizendo:\n\n2. Levanta-te, e vai à grande cidade de Nínive, e prega contra ela a pregação que eu te falo."},"body":{"pt":"1. E a palavra do SENHOR veio pela segunda vez a Jonas, dizendo:\n\n2. Levanta-te, e vai à grande cidade de Nínive, e prega contra ela a pregação que eu te falo.\n\n3. Então Jonas se levantou, e foi a Nínive, conforme a palavra do SENHOR. E Nínive era cidade extremamente grande, de três dias de caminho.\n\n4. E Jonas começou a entrar pela cidade, caminho de um dia, e pregava dizendo: Daqui a quarenta dias Nínive será destruída.\n\n5. E os homens de Nínive creram em Deus; e convocaram um jejum, e se vestiram de sacos, desde o maior até o menor deles.\n\n6. Pois quando esta palavra chegou ao rei de Nínive, ele se levantou de seu trono, e lançou de si sua roupa, e cobriu-se de saco, e se sentou em cinzas.\n\n7. E convocou e anunciou em Nínive, por mandado do rei e de seus maiorais, dizendo: Nem pessoas nem animais, nem bois nem ovelhas, provem coisa alguma, nem se lhes dê alimento, nem bebam água;\n\n8. E que as pessoas e os animais se cubram de saco, e clamem fortemente a Deus; e convertam- se cada um de seu mau caminho, e da violência que está em suas mãos.\n\n9. Quem sabe Deus mude de ideia e se arrependa, e se afaste do ardor de sua ira, para não perecermos?\n\n10. E Deus viu a atitude deles, que se converteram de seu mau caminho; então Deus se arrependeu do mal que tinha dito que lhes faria, e não o fez.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/JON03.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb),
(29, $story${"id":"biblia-livre-dan-6-16-23","type":"stories","origin":"publisher","lang":"pt","sourceCountry":"BR","rightsStatus":"licensed","source":"Bíblia Livre · edição protestante","author":"Diego Santos, Mario Sérgio e Marco Teles","title":{"pt":"Daniel na cova dos leões · Daniel 6:16–23"},"summary":{"pt":"16. Então o rei mandou trazerem a Daniel, e o lançaram na cova dos leões. E o rei falou a Daniel: O teu Deus, a quem tu serves continuamente, ele te livre.\n\n17. E foi trazida uma pedra, e foi posta sobre a abertura da cova, a qual o rei selou com seu anel, e com o anel de seus grandes, para que a sentença acerca de Daniel não fosse mudada."},"body":{"pt":"16. Então o rei mandou trazerem a Daniel, e o lançaram na cova dos leões. E o rei falou a Daniel: O teu Deus, a quem tu serves continuamente, ele te livre.\n\n17. E foi trazida uma pedra, e foi posta sobre a abertura da cova, a qual o rei selou com seu anel, e com o anel de seus grandes, para que a sentença acerca de Daniel não fosse mudada.\n\n18. Então o rei foi a seu palácio, e passou a noite em jejum; não permitiu que lhe trouxessem instrumentos musicais diante de si, e ele perdeu o sono.\n\n19. Então o rei se levantou pela manhã cedo, e foi depressa à cova dos leões.\n\n20. E chegando perto da cova, chamou a Daniel com voz triste; e o rei falou a Daniel: Daniel, servo do Deus vivente! O teus Deus, a quem tu continuamente serves, pôde te livrar dos leões?\n\n21. Então Daniel falou ao rei: Ó rei, vive para sempre!\n\n22. Meu Deus enviou seu anjo, que fechou a boca dos leões, para que não me fizessem dano; porque diante dele se achou inocência em mim; e também contra ti, ó rei, não cometi delito algum.\n\n23. Então o rei se alegrou muito por causa dele, e mandou tirar a Daniel da cova; assim Daniel foi tirado da cova, e nenhum dano se achou nele, pois havia confiado em seu Deus.\n\nEscrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos. https://creativecommons.org/licenses/by/4.0/"},"tags":["Bíblia","História bíblica"],"url":"https://ebible.org/porbr2018/DAN06.htm","license":"Escrituras em português: Bíblia Livre (BLIVRE), Copyright © Diego Santos, Mario Sérgio, e Marco Teles — fevereiro de 2018. Fonte: https://sites.google.com/site/biblialivre/ e eBible.org. Licença Creative Commons Atribuição 4.0. Palavras dos versículos reproduzidas sem alterações; apenas quebras de linha e marcadores editoriais foram omitidos.","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","resources":[["read","Fonte da Bíblia Livre","https://sites.google.com/site/biblialivre/"],["read","eBible","https://ebible.org/porbr2018/copyright.htm"]]}$story$::jsonb);

-- Release one exact Bible narrative per Brazilian calendar day. Once the
-- finite source is exhausted, return empty; never recycle or invent posts.
create function private.publish_portuguese_bible_story(p_now timestamptz default now()) returns text
language plpgsql security definer set search_path = '' as $$
declare item text; chosen integer; bible_data jsonb;
  today date := (p_now at time zone 'America/Sao_Paulo')::date;
begin
  perform pg_advisory_xact_lock(hashtext('grace-portuguese-daily-bible'));
  if p_now is null then raise exception 'invalid_time'; end if;
  if extract(hour from (p_now at time zone 'America/Sao_Paulo')) < 8 then return 'not_due'; end if;
  if exists(select 1 from private.portuguese_story_releases where published_on=today) then return 'already_published'; end if;
  select p.ordinal,p.data into chosen,bible_data from private.portuguese_bible_story_pool p
    where p.published_on is null
    and not exists(select 1 from public.content_items c where c.id=p.data->>'id')
    order by p.ordinal limit 1 for update of p;
  if chosen is null then return 'source_exhausted'; end if;
  item:=bible_data->>'id';
  insert into public.content_items(id,kind,data,published,sort_at)
    values(item,'feed',bible_data || jsonb_build_object('publishedAt',p_now),true,p_now);
  update private.portuguese_bible_story_pool set published_on=today where ordinal=chosen;
  insert into private.portuguese_story_releases(published_on,item_id,published_at) values(today,item,p_now);
  return 'published';
end $$;
revoke all on function private.publish_portuguese_bible_story(timestamptz) from public,anon,authenticated;

-- Hourly retries after 08:00 São Paulo; the release log and lock prevent
-- duplicates. This does not read web pages or accept user-supplied content.
do $$ begin
  if exists(select 1 from pg_extension where extname='pg_cron') then
    perform cron.schedule('grace-portuguese-daily-bible','17 * * * *',
      'select private.publish_portuguese_bible_story()');
  end if;
end $$;
